from typing import Annotated
from fastapi import FastAPI, Query

app = FastAPI()

@app.get("/search")
def search(q: Annotated[str, Query(min_length=3)], limit: Annotated[int, Query(ge=1, le=100)] = 10):
    return {"q": q, "limit": limit}
